#!/usr/bin/env node
/**
 * validate-activity.js
 * ─────────────────────
 * Content validator for activities generated by the IBM Bob Activity Generator.
 *
 * Usage (text report):
 *   node validate-activity.js activity.md
 *   node validate-activity.js activity.json       # parses last_message field
 *   cat activity.md | node validate-activity.js   # stdin
 *
 * Usage (JSON report):
 *   node validate-activity.js --json activity.md
 *
 * Exit codes:
 *   0 = PASS    (all TIER 1 items present)
 *   1 = FLAG    (TIER 1 items present but TIER 2 issues found)
 *   2 = FAIL    (one or more TIER 1 critical items missing)
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── CLI ──────────────────────────────────────────────────────────────────────

const args    = process.argv.slice(2);
const jsonOut = args.includes('--json');
const file    = args.find(a => !a.startsWith('--'));

let raw = '';
if (file) {
  raw = fs.readFileSync(path.resolve(file), 'utf8');
} else if (!process.stdin.isTTY) {
  raw = fs.readFileSync('/dev/stdin', 'utf8');
} else {
  console.error('Usage: node validate-activity.js [--json] <file.md|file.json>');
  process.exit(2);
}

// If input looks like NDJSON (Bob --format json output), extract last_message
if (raw.trimStart().startsWith('{')) {
  const lines = raw.split('\n').filter(l => l.trim());
  for (const line of lines) {
    try {
      const obj = JSON.parse(line);
      if (obj.type === 'result' && typeof obj.last_message === 'string') {
        raw = obj.last_message;
        break;
      }
    } catch { /* keep scanning */ }
  }
}

const text  = raw;                     // original markdown
const lower = text.toLowerCase();      // for case-insensitive keyword checks
const lines = text.split('\n');

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Return the first matching line number (1-based) and snippet, or null. */
function firstMatch(regex) {
  for (let i = 0; i < lines.length; i++) {
    if (regex.test(lines[i])) {
      return { line: i + 1, snippet: lines[i].trim().slice(0, 120) };
    }
  }
  return null;
}

/** Return all matching line numbers + snippets. */
function allMatches(regex) {
  const results = [];
  for (let i = 0; i < lines.length; i++) {
    if (regex.test(lines[i])) {
      results.push({ line: i + 1, snippet: lines[i].trim().slice(0, 120) });
    }
  }
  return results;
}

/** Extract a section's body text between two ## headings. */
function sectionBody(headingPattern) {
  const start = lines.findIndex(l => headingPattern.test(l));
  if (start === -1) return null;
  const end = lines.findIndex((l, i) => i > start && /^##\s/.test(l));
  const body = (end === -1 ? lines.slice(start + 1) : lines.slice(start + 1, end)).join('\n');
  return body.trim() || null;
}

/** Count words in a string. */
const wordCount = s => s.trim().split(/\s+/).filter(Boolean).length;

/** Sum all "N min" / "N minutes" tokens in a string. */
function sumMinutes(s) {
  let total = 0;
  for (const m of s.matchAll(/(\d+)\s*min(?:utes?)?/gi)) total += parseInt(m[1], 10);
  return total;
}

/** Extract the activity title from the first heading or first non-empty line. */
function extractTitle() {
  for (const l of lines) {
    const h = l.match(/^#{1,3}\s+(.*)/);
    if (h) return h[1].trim();
    if (l.trim()) return l.trim().slice(0, 80);
  }
  return '(untitled)';
}

// ── Section presence map ──────────────────────────────────────────────────────

const SECTIONS = {
  hook:          /^##\s.*(?:narrative\s*hook|hook|opening)/i,
  flowchart:     /^##\s.*flowchart/i,
  timeline:      /^##\s.*timeline/i,
  materials:     /^##\s.*materials/i,
  instructions:  /^##\s.*(?:step|instructions|procedure)/i,
  reflection:    /^##\s.*(?:reflection|discuss|journal)/i,
  rubric:        /^##\s.*(?:rubric|assessment|evaluat)/i,
  customization: /^##\s.*(?:customiz|personaliz)/i,
};

const sectionPresence = {};
for (const [key, re] of Object.entries(SECTIONS)) {
  sectionPresence[key] = lines.some(l => re.test(l));
}

// ── Individual checks ─────────────────────────────────────────────────────────
// Each check returns: { id, label, tier, status, evidence, recommendation }
// status: 'pass' | 'warn' | 'fail' | 'absent'

const checks = [];

function check(tier, id, label, fn) {
  const result = fn();
  checks.push({ tier, id, label, ...result });
}

// ┌─────────────────────────────────────────────────────────────────────────────┐
// │  TIER 1 — CRITICAL                                                          │
// └─────────────────────────────────────────────────────────────────────────────┘

check(1, 'section_hook', 'Narrative Hook section present', () => {
  if (sectionPresence.hook) return { status: 'pass', evidence: firstMatch(SECTIONS.hook)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a ## Narrative Hook section (2-3 sentence story or scenario to open the lesson).' };
});

check(1, 'section_timeline', 'Timeline section present', () => {
  if (sectionPresence.timeline) return { status: 'pass', evidence: firstMatch(SECTIONS.timeline)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a ## Timeline section with phase-by-phase time allocations.' };
});

check(1, 'section_materials', 'Materials section present', () => {
  if (sectionPresence.materials) return { status: 'pass', evidence: firstMatch(SECTIONS.materials)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a ## Materials section listing required resources.' };
});

check(1, 'section_instructions', 'Step-by-Step Instructions section present', () => {
  if (sectionPresence.instructions) return { status: 'pass', evidence: firstMatch(SECTIONS.instructions)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a numbered ## Step-by-Step Instructions section.' };
});

check(1, 'section_rubric', 'Assessment Rubric section present', () => {
  if (sectionPresence.rubric) return { status: 'pass', evidence: firstMatch(SECTIONS.rubric)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a ## Assessment Rubric with at least 3 criteria and 3 levels each.' };
});

check(1, 'section_customization', 'Customization Zones section present', () => {
  if (sectionPresence.customization) return { status: 'pass', evidence: firstMatch(SECTIONS.customization)?.snippet };
  return { status: 'fail', evidence: null, recommendation: 'Add a ## Customization Zones section with 📷/✏️/📝 placeholders.' };
});

check(1, 'customization_placeholders', 'Customization placeholders (📷 / ✏️ / 📝) present', () => {
  const has = /📷|✏️|📝/.test(text);
  if (has) {
    const ev = firstMatch(/📷|✏️|📝/);
    return { status: 'pass', evidence: ev?.snippet };
  }
  return { status: 'fail', evidence: null, recommendation: 'Customization Zones must include at least one 📷 / ✏️ / 📝 placeholder.' };
});

check(1, 'rubric_criteria', 'Rubric has ≥ 3 criteria', () => {
  const body = sectionBody(/^##\s.*(?:rubric|assessment|evaluat)/i);
  if (!body) return { status: 'fail', evidence: null, recommendation: 'Rubric section is missing or empty.' };
  // Count table rows or bullet/numbered items
  const tableRows = (body.match(/^\s*\|/gm) || []).filter(r => !/^\s*\|[-: |]+\|\s*$/.test(r)).length;
  const listItems = (body.match(/^[-*\d]\s+/gm) || []).length;
  const count = tableRows > 0 ? tableRows - 1 /* minus header */ : listItems; // -1 for header row
  if (count >= 3) return { status: 'pass', evidence: `${count} criteria detected` };
  return { status: 'fail', evidence: `Only ${count} rubric row(s) detected`, recommendation: 'Rubric must have at least 3 criteria.' };
});

// ┌─────────────────────────────────────────────────────────────────────────────┐
// │  TIER 2 — IMPORTANT                                                         │
// └─────────────────────────────────────────────────────────────────────────────┘

check(2, 'section_reflection', 'Reflection Questions section present', () => {
  if (sectionPresence.reflection) return { status: 'pass', evidence: firstMatch(SECTIONS.reflection)?.snippet };
  return { status: 'warn', evidence: null, recommendation: 'Add a ## Reflection Questions section with 3-5 questions.' };
});

check(2, 'reflection_count', 'Reflection has 3-5 questions', () => {
  const body = sectionBody(/^##\s.*(?:reflection|discuss|journal)/i);
  if (!body) return { status: 'warn', evidence: 'Reflection section missing', recommendation: 'Add reflection questions.' };
  const qCount = (body.match(/^\d+\.\s/gm) || []).length;
  if (qCount >= 3 && qCount <= 5) return { status: 'pass', evidence: `${qCount} question(s) detected` };
  if (qCount < 3) return { status: 'warn', evidence: `Only ${qCount} question(s)`, recommendation: 'Add more reflection questions (target: 3-5).' };
  return { status: 'warn', evidence: `${qCount} questions — may be too many`, recommendation: 'Trim to 3-5 focused questions.' };
});

check(2, 'timeline_minutes', 'Timeline contains explicit time allocations', () => {
  const body = sectionBody(/^##\s.*timeline/i);
  if (!body) return { status: 'warn', evidence: null, recommendation: 'Timeline section missing.' };
  const total = sumMinutes(body);
  const phaseMatches = allMatches(/\d+\s*min/i);
  if (total === 0) return { status: 'warn', evidence: 'No "N min" time tokens found', recommendation: 'Add explicit time allocations to each phase (e.g. "10 min").' };
  return { status: 'pass', evidence: `${total} total minutes across ${phaseMatches.length} time token(s)` };
});

check(2, 'hook_length', 'Narrative Hook is 2-3 sentences', () => {
  const body = sectionBody(/^##\s.*(?:narrative\s*hook|hook|opening)/i);
  if (!body) return { status: 'warn', evidence: null, recommendation: 'Narrative Hook missing.' };
  const sentences = body.split(/[.!?]+/).filter(s => s.trim().length > 10).length;
  if (sentences >= 2 && sentences <= 4) return { status: 'pass', evidence: `~${sentences} sentence(s)` };
  if (sentences < 2) return { status: 'warn', evidence: `Only ~${sentences} sentence(s)`, recommendation: 'Expand the Narrative Hook to 2-3 engaging sentences.' };
  return { status: 'warn', evidence: `~${sentences} sentences — may be too long`, recommendation: 'Trim the Narrative Hook to 2-3 sentences.' };
});

check(2, 'ambiguous_instructions', 'No unresolved ambiguous instructions', () => {
  const patterns = /\b(if applicable|depending on|optional(?! follow-up))\b/gi;
  const hits = allMatches(patterns);
  if (hits.length === 0) return { status: 'pass', evidence: 'No ambiguous phrasing detected' };
  return {
    status: 'warn',
    evidence: hits.map(h => `L${h.line}: ${h.snippet}`).join(' | '),
    recommendation: `Resolve or qualify the ${hits.length} ambiguous instruction phrase(s): "if applicable", "depending on", bare "optional".`,
  };
});

check(2, 'misconception_addressed', 'Common misconceptions or false-premise traps mentioned', () => {
  const m = firstMatch(/misconception|common\s+error|common\s+mistake|false\s+premise|trap|pitfall/i);
  if (m) return { status: 'pass', evidence: `L${m.line}: ${m.snippet}` };
  return { status: 'warn', evidence: null, recommendation: 'Consider adding a note on common misconceptions or false premises students may bring to this topic.' };
});

check(2, 'instructions_numbered', 'Step-by-Step Instructions use numbered steps', () => {
  const body = sectionBody(/^##\s.*(?:step|instructions|procedure)/i);
  if (!body) return { status: 'warn', evidence: null };
  const numbered = (body.match(/^\s*\d+\.\s/gm) || []).length;
  if (numbered >= 3) return { status: 'pass', evidence: `${numbered} numbered step(s)` };
  return { status: 'warn', evidence: `Only ${numbered} numbered step(s)`, recommendation: 'Use numbered list format for instructions so teachers can follow sequentially.' };
});

// ┌─────────────────────────────────────────────────────────────────────────────┐
// │  TIER 3 — NICE-TO-HAVE                                                      │
// └─────────────────────────────────────────────────────────────────────────────┘

check(3, 'data_citations', 'Data citations or references present', () => {
  const m = firstMatch(/https?:\/\/|www\.|(?:\[[\w\s,\.]+\])|(?:^\s*>\s*\[?\d+\]?)/i);
  if (m) return { status: 'pass', evidence: `L${m.line}: ${m.snippet}` };
  return { status: 'absent', evidence: null, recommendation: 'Consider linking to a source, dataset, or reference for factual claims.' };
});

check(3, 'section_flowchart', 'Mermaid Flowchart section present', () => {
  if (sectionPresence.flowchart) return { status: 'pass', evidence: firstMatch(SECTIONS.flowchart)?.snippet };
  const mermaidBlock = firstMatch(/^```mermaid/i);
  if (mermaidBlock) return { status: 'pass', evidence: `L${mermaidBlock.line}: mermaid block found` };
  return { status: 'absent', evidence: null, recommendation: 'A ## Flowchart section with a Mermaid TD diagram helps teachers visualize the activity flow.' };
});

check(3, 'cross_curricular', 'Cross-curricular connection mentioned', () => {
  const m = firstMatch(/cross.curricular|interdisciplin|connect(s|ing)?\s+to\s+(art|science|history|math|literacy|geography|music)/i);
  if (m) return { status: 'pass', evidence: `L${m.line}: ${m.snippet}` };
  return { status: 'absent', evidence: null, recommendation: 'Adding a cross-curricular link broadens the activity\'s usefulness.' };
});

check(3, 'low_resource_friendly', 'Low-resource / no-tech alternatives mentioned', () => {
  const m = firstMatch(/no\s+(computer|screen|internet|tech|device)|low.resource|without\s+internet|paper.based|offline/i);
  if (m) return { status: 'pass', evidence: `L${m.line}: ${m.snippet}` };
  return { status: 'absent', evidence: null, recommendation: 'Mention a low-resource or offline alternative to increase global accessibility.' };
});

// ── Build report ─────────────────────────────────────────────────────────────

const title          = extractTitle();
const critical       = checks.filter(c => c.tier === 1);
const important      = checks.filter(c => c.tier === 2);
const niceToHave     = checks.filter(c => c.tier === 3);
const hasFail        = critical.some(c => c.status === 'fail');
const hasWarn        = important.some(c => c.status === 'warn');
const overallStatus  = hasFail ? 'FAIL' : hasWarn ? 'FLAG' : 'PASS';
const recommendations = checks.filter(c => c.recommendation).map(c => c.recommendation);

const EMOJI = {
  pass:   '🟢 PASS',
  warn:   '🟡 WARN',
  fail:   '🔴 FAIL',
  absent: '🔵 ABSENT',
};

// ── JSON output ───────────────────────────────────────────────────────────────

if (jsonOut) {
  const toItem = c => ({
    id:             c.id,
    item:           c.label,
    status:         EMOJI[c.status],
    evidence:       c.evidence ?? null,
    recommendation: c.recommendation ?? null,
  });
  const report = {
    activity_title:    title,
    overall_status:    overallStatus,
    critical_items:    critical.map(toItem),
    important_items:   important.map(toItem),
    nice_to_have_items: niceToHave.map(toItem),
    recommendations,
  };
  console.log(JSON.stringify(report, null, 2));
  process.exit(hasFail ? 2 : hasWarn ? 1 : 0);
}

// ── Text report ───────────────────────────────────────────────────────────────

const HR  = '─'.repeat(64);
const HR2 = '━'.repeat(64);

function printSection(label, items) {
  console.log(`\n${HR}`);
  console.log(`  ${label}`);
  console.log(HR);
  for (const c of items) {
    const badge = EMOJI[c.status];
    console.log(`  ${badge.padEnd(14)} ${c.label}`);
    if (c.evidence)       console.log(`               ↳ ${c.evidence}`);
    if (c.recommendation) console.log(`               💡 ${c.recommendation}`);
  }
}

console.log('\n' + HR2);
console.log(`  ACTIVITY VALIDATOR REPORT`);
console.log(HR2);
console.log(`  Title   : ${title}`);
console.log(`  Status  : ${overallStatus === 'PASS' ? '🟢' : overallStatus === 'FLAG' ? '🟡' : '🔴'}  ${overallStatus}`);
console.log(HR2);

printSection('TIER 1 — CRITICAL (must pass for activity to be shown)', critical);
printSection('TIER 2 — IMPORTANT (quality issues)', important);
printSection('TIER 3 — NICE-TO-HAVE (enhancements)', niceToHave);

if (recommendations.length) {
  console.log(`\n${HR}`);
  console.log('  RECOMMENDATIONS');
  console.log(HR);
  recommendations.forEach((r, i) => console.log(`  ${i + 1}. ${r}`));
}

console.log('\n' + HR2 + '\n');

process.exit(hasFail ? 2 : hasWarn ? 1 : 0);
